SELECT DISTINCT `e`.`type` AS `event_category`
FROM `student_club`.`bird`.`event` AS `e`
WHERE `e`.`location` = "MU 215";

SELECT AVG(CASE WHEN `c`.`layout` = "normal" THEN 100.0 ELSE 0.0 END) AS `textless_normal_layout_proportion_pct`
FROM `card_games`.`bird`.`cards` AS `c`
WHERE `c`.`isTextless` = 1;
